<template><main class="login-shell"><div class="login-card"><div class="brand">⚡ 新能源调控平台</div><p class="eyebrow">SECURE ADMIN CONSOLE</p><h1>管理系统登录</h1><form @submit.prevent="submit"><label>管理员账号<input v-model="username" autocomplete="username" /></label><label>管理员密码<input v-model="password" type="password" autocomplete="current-password" /></label><button :disabled="loading">{{ loading ? '验证中…' : '登录管理系统' }}</button><p v-if="error" class="error">{{ error }}</p></form><RouterLink to="/dashboard">返回大屏</RouterLink></div></main></template>
<script setup lang="ts">
import { ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { http } from '../../api/http'
const router = useRouter(); const username = ref(''); const password = ref(''); const error = ref(''); const loading = ref(false)
async function submit(){ loading.value=true; error.value=''; try { const result=(await http.post<{token:string}>('/auth/login',{username:username.value,password:password.value})).data; localStorage.setItem('admin_token',result.token); router.push('/admin') } catch { error.value='账号或密码错误' } finally { loading.value=false } }
</script>
<style scoped>.login-shell{min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 50% 35%,#0d3850,#06131f 65%);color:#e3f8ff}.login-card{width:360px;padding:34px;background:rgba(7,27,44,.9);border:1px solid rgba(79,199,231,.35);box-shadow:0 0 45px rgba(37,173,214,.12)}.brand{color:#b8edf8;font-size:16px;margin-bottom:34px}.eyebrow{color:#55cdeb;font-size:10px;letter-spacing:.2em}.login-card h1{margin:10px 0 26px;font-size:26px}.login-card label{display:block;color:#87aaba;font-size:11px;margin:15px 0}.login-card input{display:block;width:100%;box-sizing:border-box;margin-top:7px;padding:11px;background:#071b2b;border:1px solid rgba(88,184,218,.3);color:#e3f8ff}.login-card button{width:100%;margin-top:12px;padding:12px;background:#1d819d;border:0;color:#fff;cursor:pointer}.login-card a{display:block;margin-top:20px;color:#62d7f5;font-size:11px;text-align:center}.error{color:#ff8b7c;font-size:11px}</style>
